package com.procurement.purchaseorder.controller;import com.procurement.common.response.*;import com.procurement.purchaseorder.dto.response.*;import com.procurement.purchaseorder.service.*;import org.springframework.data.domain.*;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/purchase-order-lines")public class PurchaseOrderLineController{private final PurchaseOrderService s;public PurchaseOrderLineController(PurchaseOrderService s){this.s=s;}@GetMapping public ApiResponse<PageResponse<PurchaseOrderLineResponse>>search(@RequestParam Long purchaseOrderId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.success(s.lines(purchaseOrderId,PageRequest.of(page,size,Sort.by("id"))));}@GetMapping("/{id}")public ApiResponse<PurchaseOrderLineResponse>get(@PathVariable Long id){return ApiResponse.success(s.line(id));}}
